/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: manualReview, mount
 * Tests
 *   - manual saved differences identify the original values and distinguish an Album from a same-named track without Luna
 *   - the counted update action confirms only explicitly selected saved fields
 *   - a source that cannot be applied preserves readable differences and disables selection and confirmation
 *   - the confirmation summary presents the supplied old and new values without interactive selection
 *   - a saved Disc Number difference is selectable as a Track Disc number change with its frozen old and new values
 *   - a number lookup filled through its pairing waits for the expected tracklist: shown, never selectable or confirmed, while the title still applies
 * @end-catalog */

import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { CatalogReviewApply, CatalogReviewChangeSummary } from './CatalogReviewApply';
import { capturedCatalogReview, catalogReview, session, slotId, slotTwo, viewer } from './catalogReviewFixtures.testSupport';
import { reviewAfterLookup, reviewLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import type { ReviewLookupResponse } from './catalogReviewLookupApi';
import { catalogReviewKey } from './catalogReviewSummaryQuery';
import { reviewChanges, reviewFieldKey, type CatalogReview, type ReviewChange } from './catalogReviewApi';

beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); });

function manualReview(): CatalogReview {
  const item = catalogReview();
  item.analysis = { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 };
  item.suggestions = [];
  item.source.album.title = item.source.tracks[0].title = 'Shared synthetic name';
  item.draft.album.title = 'Manual Album correction';
  item.draft.tracks[0].title = 'Manual track correction';
  return item;
}

/** Renders the step; `lookup` stands in for the lookup summary's cached read of the item's revision. */
function mount(item = manualReview(), selected: ReviewChange[] = [], lookup?: ReviewLookupResponse) {
  const onSelect = vi.fn(), onConfirm = vi.fn(), client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  const capture = adminWorkspace.capture();
  if (lookup) client.setQueryData([...catalogReviewKey(capture, item.id), 'lookup', item.revision], lookup);
  render(<QueryClientProvider client={client}><CatalogReviewApply item={item} changes={reviewChanges(item)} selected={selected} disabled={false} onSelect={onSelect} onConfirm={onConfirm} /></QueryClientProvider>);
  return { onSelect, onConfirm };
}

test('manual saved differences identify the original values and distinguish an Album from a same-named track without Luna', () => {
  const item = manualReview(), { onSelect } = mount(item);
  const album = screen.getByRole('checkbox', { name: 'Update Album · Shared synthetic name · Title' });
  const track = screen.getByRole('checkbox', { name: 'Update Track · Shared synthetic name · Title' });
  expect(within(album.closest('article')!).getByText('Original Album information')).toBeVisible();
  expect(within(album.closest('article')!).getByText('Value to apply')).toBeVisible();
  expect(within(album.closest('article')!).getByText('Manual Album correction')).toBeVisible();
  expect(within(track.closest('article')!).getByText('Manual track correction')).toBeVisible();
  expect(screen.queryByText('When Luna AI ran')).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Update original Album (0)' })).toBeDisabled();
  fireEvent.click(track);
  expect(onSelect).toHaveBeenCalledWith(reviewFieldKey(reviewChanges(item)[1]), true);
});

test('the counted update action confirms only explicitly selected saved fields', () => {
  const item = manualReview(), selected = [reviewChanges(item)[1]];
  const { onConfirm } = mount(item, selected);
  fireEvent.click(screen.getByRole('button', { name: 'Update original Album (1)' }));
  expect(onConfirm).toHaveBeenCalledWith([{ scope: 'track', slotId, field: 'title' }]);
  expect(screen.getByRole('checkbox', { name: 'Update Album · Shared synthetic name · Title' })).not.toBeChecked();
  expect(screen.getByRole('checkbox', { name: 'Update Track · Shared synthetic name · Title' })).toBeChecked();
});

test('a source that cannot be applied preserves readable differences and disables selection and confirmation', () => {
  const item = manualReview();
  item.sourceStatus = 'changed';
  item.capabilities.apply = false;
  const { onSelect, onConfirm } = mount(item, [reviewChanges(item)[0]]);
  screen.getAllByRole('checkbox').forEach(input => expect(input).toBeDisabled());
  const button = screen.getByRole('button', { name: 'Update original Album (1)' });
  expect(button).toBeDisabled();
  fireEvent.click(button);
  expect(onConfirm).not.toHaveBeenCalled();
  expect(onSelect).not.toHaveBeenCalled();
  expect(screen.getByText('Manual Album correction')).toBeVisible();
});

test('the confirmation summary presents the supplied old and new values without interactive selection', () => {
  const frozen = structuredClone(reviewChanges(manualReview())[1]);
  render(<CatalogReviewChangeSummary change={frozen} />);
  expect(screen.getByRole('heading', { name: 'Update Track · Shared synthetic name · Title' })).toBeVisible();
  expect(screen.getByText('Shared synthetic name')).toBeVisible();
  expect(screen.getByText('Manual track correction')).toBeVisible();
  expect(screen.queryByRole('checkbox')).not.toBeInTheDocument();
  expect(screen.queryByRole('button')).not.toBeInTheDocument();
});

test('a saved Disc Number difference is selectable as a Track Disc number change with its frozen old and new values', () => {
  const item = catalogReview(); item.suggestions = []; item.draft.tracks[0].discNumber = 2;
  const { onConfirm } = mount(item, reviewChanges(item));
  const disc = screen.getByRole('checkbox', { name: 'Update Track · Synthetic first track · Disc number' });
  expect(within(disc.closest('article')!).getByText('—')).toBeVisible();
  expect(within(disc.closest('article')!).getByText('2')).toBeVisible();
  fireEvent.click(screen.getByRole('button', { name: 'Update original Album (1)' }));
  expect(onConfirm).toHaveBeenCalledWith([{ scope: 'track', slotId, field: 'discNumber' }]);
});

test('a number lookup filled through its pairing waits for the expected tracklist: shown, never selectable or confirmed, while the title still applies', () => {
  const item = reviewAfterLookup(capturedCatalogReview()); item.draft.album.title = 'Manual Album correction';
  const changes = reviewChanges(item), number = changes.find(change => change.slotId === slotTwo && change.field === 'trackNumber')!;
  expect(number).toMatchObject({ baseline: null, value: 3 });
  const { onConfirm } = mount(item, changes, reviewLookupResponse());
  const box = screen.getByRole('checkbox', { name: 'Update Track · Synthetic second track · Track number' });
  expect(box).toBeDisabled(); expect(box).not.toBeChecked();
  expect(box).toHaveAccessibleDescription('Applies together with the expected tracklist');
  expect(screen.getByRole('checkbox', { name: 'Update Album · Synthetic catalog Album · Title' })).toBeChecked();
  fireEvent.click(screen.getByRole('button', { name: `Update original Album (${changes.length - 1})` }));
  expect(onConfirm.mock.calls[0][0]).not.toContainEqual({ scope: 'track', slotId: slotTwo, field: 'trackNumber' });
  expect(onConfirm.mock.calls[0][0]).toContainEqual({ scope: 'album', slotId: null, field: 'title' });
  cleanup();
  // A number edited since, or one an answer took from a conflict, is the administrator's and stays selectable; so is any without a read.
  const edited = reviewAfterLookup(capturedCatalogReview()); edited.draft.tracks[1].trackNumber = 4;
  mount(edited, [], reviewLookupResponse());
  expect(screen.getByRole('checkbox', { name: 'Update Track · Synthetic second track · Track number' })).toBeEnabled();
  cleanup();
  const answered = reviewLookupResponse();
  answered.lookup!.applied!.conflicts.push({ path: `tracks.${slotTwo}.trackNumber`, slotId: slotTwo, lookup: 3, answer: 'lookup', musicBrainzId: false, precision: false });
  mount(reviewAfterLookup(capturedCatalogReview()), [], answered);
  expect(screen.getByRole('checkbox', { name: 'Update Track · Synthetic second track · Track number' })).toBeEnabled();
  cleanup();
  mount(reviewAfterLookup(capturedCatalogReview()));
  expect(screen.getByRole('checkbox', { name: 'Update Track · Synthetic second track · Track number' })).toBeEnabled();
});
